def f(I):
    H=len(I); W=len(I[0])
    colors=set(c for row in I for c in row if c)
    pieces={}
    for v in colors:
        pcs=comps(I,v)
        pieces[v]=pcs
    # band assignment: leftmost color -> band 0
    leftmost=min(min(c for r in range(H) for c in range(W) if I[r][c]==v) for v in colors)
    left_colors={v for v in colors if min(c for r in range(H) for c in range(W) if I[r][c]==v)==leftmost}
    assert len(left_colors)==1, left_colors
    lv=list(left_colors)[0]
    def band(v):
        if v==lv: return 0
        mx=max(max(c for r,c in pcs) for pcs in pieces[v])
        return min(band(x) for x in colors if x!=lv)+2
    out=[[0]*W for _ in range(H)]
    for v in colors:
        bs=band(v)
        # stack bottom-up: size desc, height desc, input order
        pcs=sorted(pieces[v], key=lambda p: (-len(p), -(max(r for r,_ in p)-min(r for r,_ in p)), True))
        cur_bottom=H-1
        for p in pcs:
            h=max(r for r,_ in p)-min(r for r,_ in p)+1
            top=cur_bottom-h+1
            if top<0: top=0
            for (r,c) in p:
                rr,cc=top+r-min(r for r,_ in p), bs+c-min(c for _,c in p)
                out[rr][cc]=v
            cur_bottom=top-2  # one empty row gap
        # safety clamp
        if cur_bottom>H-1: cur_bottom=H-1
    return out
